tests/price_test.sh.text:
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
# 10% off rounded down (PRC-501): 999*0.9=899.1 -> 899, 5*0.9=4.5 -> 4
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999: $(bash bin/price 999)"; fail=1; }
[ "$(bash bin/price 5)" = 4 ] || { echo "price 5: $(bash bin/price 5)"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999: $(bash bin/quote 999)"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999: $(bash lib/invoice.sh 999)"; fail=1; }
[ "$(bash lib/statement.sh 999)" = "statement member 899" ] || { echo "statement 999: $(bash lib/statement.sh 999)"; fail=1; }
exit $fail

tests/statement_test.sh.text:
#!/bin/bash
fail=0
[ -n "$(bash lib/statement.sh 1000)" ] || { echo "statement prints nothing"; fail=1; }
exit $fail

